/**
 * Rahab and the Spies
 * -------------------
 * Two spies are hidden by Rahab the prostitute on the wall of Jericho, and she marks the scarlet cord in the window. Stage: a city wall at night, a rooftop with flax, two men in the dark, a scarlet cord at the window; the sound of a closing gate, a bargain of faith.
 *
 * Palette 0x2d1a0e → 0x060402 · light: dusk · hero: gate
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./joshua-kit.js.
 */

import { THREE, createScene, cityGate, house, person, birds } from './joshua-kit.js';

const BG = 0x2d1a0e;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 4168344030, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [15, 0, -58], { name: 'city', r: [0, 0.11, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x060402, trim: 0x050302 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x060402 });
    }
    W.backdrop(city);

    /* hero: the gate */
    cityGate(W, group, 0, 0, -6, 1.0, { stone: 0x060402, trim: 0x050302 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x2d1a0e, ry: 0.39, s: 1.07 });

    /* birds: slow circles high above */
    birds(W, group, 5, 55, { y: 26 });

    return W.finish();
}

export default { build };
